(function($) {
    'use strict';
    
    // Newsletter Subscription Handler
    function initNewsletterSubscription() {
        $('#nk-subscribe-form').on('submit', function(e) {
            e.preventDefault();
            
            var $form = $(this);
            var $email = $('#nk-subscribe-email');
            var $submitBtn = $('#nk-subscribe-btn');
            var $messages = $('.nksp-form-messages');
            var $btnText = $submitBtn.find('.btn-text');
            var $btnLoading = $submitBtn.find('.btn-loading');
            
            // Reset messages
            $messages.removeClass('nksp-message-success nksp-message-error').html('');
            
            // Validate email
            var email = $email.val().trim();
            if (!isValidEmail(email)) {
                showMessage($messages, 'Please enter a valid email address.', 'error');
                return;
            }
            
            // Show loading state
            $btnText.hide();
            $btnLoading.show();
            $submitBtn.prop('disabled', true);
            
            // AJAX request
            $.ajax({
                url: nksp_ajax.ajax_url,
                type: 'POST',
                data: {
                    action: 'nk_subscribe_email',
                    email: email,
                    security: $('input[name="subscription_nonce"]').val()
                },
                success: function(response) {
                    if (response.success) {
                        showMessage($messages, response.data, 'success');
                        $form[0].reset(); // Clear form
                    } else {
                        showMessage($messages, response.data, 'error');
                    }
                },
                error: function() {
                    showMessage($messages, 'Something went wrong. Please try again.', 'error');
                },
                complete: function() {
                    // Reset button state
                    $btnText.show();
                    $btnLoading.hide();
                    $submitBtn.prop('disabled', false);
                }
            });
        });
    }
    
    function isValidEmail(email) {
        var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email);
    }
    
    function showMessage($container, message, type) {
        $container.removeClass('nksp-message-success nksp-message-error')
                 .addClass('nksp-message-' + type)
                 .html('<span class="nksp-message-text">' + message + '</span>');
        
        // Auto-hide success messages after 5 seconds
        if (type === 'success') {
            setTimeout(function() {
                $container.removeClass('nksp-message-success').html('');
            }, 5000);
        }
    }
    
    // Initialize when document is ready
    $(document).ready(function() {
        initNewsletterSubscription();
        
        // Add AJAX URL to frontend
        if (typeof nksp_ajax === 'undefined') {
            var nksp_ajax = {
                ajax_url: '<?php echo admin_url("admin-ajax.php"); ?>'
            };
        }
    });
    
})(jQuery);